import 'dotenv/config'
import { schema } from '@api/src/graphql/schema'
import { type CodegenConfig, generate } from '@graphql-codegen/cli'
import { printSchema } from 'graphql'

async function codegen() {
  const config: CodegenConfig = {
    overwrite: true,
    schema: printSchema(schema),
    require: ['tsconfig-paths/register'],
    verbose: true,
    generates: {
      './shared/graphql/types.ts': {

        plugins: ['typescript', 'typescript-resolvers'],
        config: {
          enumsAsTypes: true,
          makeResolverTypeCallable: true,

          contextType: '@shared/graphql/context#GraphQLContext',
        },
      },

      './api/lib/graphql/schema.graphql': {
        plugins: ['schema-ast'],
        config: {
          includeDirectives: true,
        },
      },
    },
  }
  await generate(config, true)
}
export default codegen().catch((err) => {
  process.exit(1)
})
